283	// isOutdated compares current and latest versions using semantic versioning.
284	// Returns true if current < latest.
285	func isOutdated(current, latest string) bool {
286		// Ensure versions have "v" prefix for semver package
287		if !strings.HasPrefix(current, "v") {
288			current = "v" + current
289		}
290		if !strings.HasPrefix(latest, "v") {
291			latest = "v" + latest
292		}
293	
294		// Skip notification for dev builds (e.g., "1.0.0-dev-xxx").
295		// These are local development builds and shouldn't trigger update notifications.
296		// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
297		if strings.Contains(semver.Prerelease(current), "dev") {
298			return false
299		}
300	
301		// semver.Compare returns -1 if current < latest
302		return semver.Compare(current, latest) < 0
303	}
