316	func installManagerForCurrentBinary() string {
317		execPath, err := executablePath()
318		if err != nil {
319			return installManagerUnknown
320		}
321	
322		realPath, err := filepath.EvalSymlinks(execPath)
323		if err != nil {
324			realPath = execPath
325		}
326		normalizedPath := strings.ReplaceAll(filepath.ToSlash(realPath), "\\", "/")
327	
328		switch {
329		case strings.Contains(normalizedPath, "/Cellar/") ||
330			strings.Contains(normalizedPath, "/opt/homebrew/") ||
331			strings.Contains(normalizedPath, "/linuxbrew/") ||
332			strings.Contains(normalizedPath, "/Caskroom/"):
333			return installManagerBrew
334		case strings.Contains(normalizedPath, "/mise/installs/"):
335			return installManagerMise
336		case strings.Contains(normalizedPath, "/scoop/apps/"):
337			return installManagerScoop
338		default:
339			return installManagerUnknown
340		}
341	}
