343	// updateCommand returns the appropriate update instruction based on how the binary was installed.
344	func updateCommand(currentVersion string) string {
345		switch installManagerForCurrentBinary() {
346		case installManagerBrew:
347			if releaseChannel(currentVersion) == installChannelNightly {
348				return "brew upgrade --cask entire@nightly"
349			}
350			return "brew upgrade --cask entire"
351		case installManagerMise:
352			return "mise upgrade entire"
353		case installManagerScoop:
354			return "scoop update entire/cli"
355		}
356	
357		if releaseChannel(currentVersion) == installChannelNightly {
358			return "curl -fsSL https://entire.io/install.sh | bash -s -- --channel nightly"
359		}
360		return "curl -fsSL https://entire.io/install.sh | bash"
361	}
