363	// printNotification prints the version update notification to the user.
364	func printNotification(w io.Writer, current, latest string) {
365		msg := fmt.Sprintf("\nA newer version of Entire CLI is available: %s (current: %s)\nRun '%s' to update.\n",
366			latest, current, updateCommand(current))
367		fmt.Fprint(w, msg)
368	}
